#!/usr/bin/env python3
"""Compile actual updater with explicit Android/HTTP doubles; never install or run root."""
from pathlib import Path
import argparse, subprocess, tempfile, json, hashlib
ROOT=Path(__file__).resolve().parents[1]
FIXTURES={'Context.kt': 'package android.content\nimport java.io.File\nimport android.content.pm.PackageManager\nopen class Context(val cacheDir:File,val packageName:String="com.waenhancer",val packageManager:PackageManager=PackageManager())\nopen class ContextWrapper(val baseContext:Context):Context(baseContext.cacheDir,baseContext.packageName,baseContext.packageManager)\nclass Intent(val action:String="",val uri:android.net.Uri?=null) {\n fun setDataAndType(u:android.net.Uri,t:String)=this;fun addFlags(f:Int)=this\n companion object{const val ACTION_VIEW="VIEW";const val FLAG_GRANT_READ_URI_PERMISSION=1;const val FLAG_ACTIVITY_NEW_TASK=2}\n}\n', 'Activity.kt': 'package android.app\nimport android.content.*\nimport java.io.File\nopen class Activity(cache:File):Context(cache){fun runOnUiThread(f:()->Unit){f()};fun startActivity(i:Intent){throw AssertionError("Installation forbidden in probe")}}\n', 'PackageManager.kt': 'package android.content.pm\nclass PackageInfo(val packageName:String,val versionName:String?)\nclass PackageManager {\n var beforeRead:(()->Unit)?=null\n fun getPackageArchiveInfo(path:String,flags:Int):PackageInfo?{beforeRead?.invoke();return PackageInfo("com.waenhancer","2.0.3")}\n fun canRequestPackageInstalls()=true\n}\n', 'Uri.kt': "package android.net\nclass Uri private constructor(val value:String){val lastPathSegment:String? get()=java.net.URI(value).path?.substringAfterLast('/')\n companion object {fun parse(s:String)=Uri(s)}}\n", 'Os.kt': 'package android.os\nobject Build {object VERSION {const val SDK_INT=34};object VERSION_CODES {const val O=26}}\nclass Looper {companion object {fun getMainLooper()=Looper()}}\nclass Handler(l:Looper){fun postDelayed(f:()->Unit,t:Long){throw AssertionError("Unexpected delayed install")}}\nobject Process{fun myPid()=1;fun killProcess(pid:Int){throw AssertionError("Process kill forbidden")}}\n\nobject SystemClock{var time=0L;fun elapsedRealtime()=time}\n', 'Settings.kt': 'package android.provider\nobject Settings {const val ACTION_MANAGE_UNKNOWN_APP_SOURCES="UNKNOWN"}\n', 'Toast.kt': 'package android.widget\nclass Toast{fun show(){};companion object{const val LENGTH_LONG=1;fun makeText(c:android.content.Context,t:String,d:Int)=Toast()}}\n', 'FileProvider.kt': 'package androidx.core.content\nobject FileProvider{fun getUriForFile(c:android.content.Context,s:String,f:java.io.File)=android.net.Uri.parse(f.toURI().toString())}\n', 'Http.kt': 'package okhttp3\nimport java.io.*\nimport java.util.concurrent.TimeUnit\nclass HttpUrl(val text:String){val scheme:String get()=java.net.URI(text).scheme?:""}\nclass Request(val url:HttpUrl){class Builder{var text="";fun url(s:String)=apply{java.net.URI(s);require(s.startsWith("http://")||s.startsWith("https://"));text=s};fun build()=Request(HttpUrl(text))}}\ninterface Call{fun cancel();fun isCanceled():Boolean;fun enqueue(callback:Callback)}\ninterface Callback{fun onFailure(call:Call,e:IOException);fun onResponse(call:Call,response:Response)}\nclass Body(val bytes:ByteArray,val length:Long=bytes.size.toLong()){\n fun contentLength()=length\n fun byteStream():InputStream=object:ByteArrayInputStream(bytes){override fun read(b:ByteArray,o:Int,l:Int):Int{android.os.SystemClock.time++;return super.read(b,o,l)}}\n}\nclass Response(val request:Request,val body:Body?,val code:Int=200):Closeable{val isSuccessful:Boolean get()=code in 200..299;override fun close(){}}\nclass FakeCall(val request:Request):Call{var cancelled=false;lateinit var callback:Callback\n override fun cancel(){cancelled=true};override fun isCanceled()=cancelled\n override fun enqueue(callback:Callback){this.callback=callback}\n fun finish(bytes:ByteArray){callback.onResponse(this,Response(request,Body(bytes)))}}\nobject Network {val calls=mutableListOf<FakeCall>();fun reset(){calls.clear()}}\nclass OkHttpClient {class Builder {fun connectTimeout(t:Long,u:TimeUnit)=this;fun readTimeout(t:Long,u:TimeUnit)=this;fun followSslRedirects(v:Boolean)=this;fun build()=OkHttpClient()}\n fun newCall(r:Request):Call=FakeCall(r).also{Network.calls.add(it)}}\n', 'Normalize.kt': 'package com.waenhancer.update\nfun normalizeVersion(value: String): String = value.trim().removePrefix("v").removePrefix("V").substringBefore(\'+\').trim()\n', 'Checks.kt': 'package com.waenhancer.update\nimport java.io.*\nimport java.util.zip.*\nimport java.security.MessageDigest\nimport android.content.Context\nimport okhttp3.*\nclass Capture:UpdateDownloader.DownloadCallback {\n val files=mutableListOf<File>();val failures=mutableListOf<Exception>();var progresses=0;var failSuccess=false;var cancelOnComplete:(()->Unit)?=null\n override fun onProgress(p:Int,c:Long,t:Long){progresses++;if(p==100)cancelOnComplete?.invoke()}\n override fun onSuccess(f:File){files.add(f);if(failSuccess)throw IllegalStateException("consumer failed")}\n override fun onFailure(e:Exception){failures.add(e)}\n}\nfun apk(seed:Long):ByteArray {val b=ByteArrayOutputStream();ZipOutputStream(b).use{z->for(n in listOf("AndroidManifest.xml","classes.dex")){z.putNextEntry(ZipEntry(n));val data=ByteArray(2048);java.util.Random(seed).nextBytes(data);z.write(data);z.closeEntry()}};return b.toByteArray()}\nfun hash(b:ByteArray)=MessageDigest.getInstance("SHA-256").digest(b).joinToString(""){"%02x".format(it.toInt() and 255)}\nvar count=0\nfun test(name:String,f:()->Unit){f();count++;println("PASS $name")}\nfun main(args:Array<String>){\n val root=File(args[0]);root.mkdirs();val old=apk(1);val good=apk(2);val url="https://example.invalid/module.apk"\n fun context(name:String)=Context(File(root,name).also{it.mkdirs()})\n fun start(c:Context,b:Capture,h:String?=null,s:Long=0):FakeCall {Network.reset();UpdateDownloader.downloadApk(c,url,"2.0.3",b,h,s);return Network.calls.single()}\n test("republication never reuses filename/version cache") {val c=context("cache");File(c.cacheDir,"module.apk").writeBytes(old);val b=Capture();val call=start(c,b);check(b.files.isEmpty());call.finish(good);check(b.files.single().readBytes().contentEquals(good))}\n test("HTTP rejected before cache/filesystem") {val c=context("http");File(c.cacheDir,"module.apk").writeBytes(old);Network.reset();val b=Capture();check(UpdateDownloader.downloadApk(c,url.replace("https:","http:"),"2.0.3",b)==null);check(b.failures.size==1&&Network.calls.isEmpty())}\n test("concurrent handoffs immutable") {val c=context("concurrent");val a=Capture();val b=Capture();val one=start(c,a);val two=start(c,b);one.finish(old);val file=a.files.single();two.finish(good);check(file!=b.files.single());check(file.readBytes().contentEquals(old))}\n test("cancel during Android validation") {val c=context("cancel");val b=Capture();val call=start(c,b);c.packageManager.beforeRead={call.cancel()};call.finish(good);check(b.files.isEmpty()&&b.failures.isEmpty());check(c.cacheDir.listFiles()!!.isEmpty())}\n test("cancel before response") {val c=context("early");val b=Capture();val call=start(c,b);call.cancel();call.finish(good);check(b.files.isEmpty()&&c.cacheDir.listFiles()!!.isEmpty())}\n test("cancel on complete progress") {val c=context("late");val b=Capture();val call=start(c,b);b.cancelOnComplete={call.cancel()};call.finish(good);check(b.files.isEmpty()&&c.cacheDir.listFiles()!!.isEmpty())}\n test("successful SHA-256 and size") {val c=context("valid");val b=Capture();start(c,b,hash(good),good.size.toLong()).finish(good);check(b.files.size==1&&b.failures.isEmpty())}\n test("corruption rejected and staging removed") {val c=context("digest");val b=Capture();start(c,b,hash(old)).finish(good);check(b.files.isEmpty()&&b.failures.size==1&&c.cacheDir.listFiles()!!.isEmpty())}\n test("size mismatch") {val c=context("size");val b=Capture();start(c,b,null,good.size+1L).finish(good);check(b.files.isEmpty()&&b.failures.size==1)}\n test("content length mismatch") {val c=context("length");val b=Capture();val call=start(c,b);call.callback.onResponse(call,Response(call.request,Body(good,good.size+1L)));check(b.files.isEmpty()&&b.failures.size==1)}\n test("insecure final redirect rejected") {val c=context("redirect");val b=Capture();val call=start(c,b);call.callback.onResponse(call,Response(Request(HttpUrl("http://example.invalid/a")),Body(good)));check(b.files.isEmpty()&&b.failures.size==1)}\n test("consumer exception retains handoff ownership") {val c=context("consumer");val b=Capture();b.failSuccess=true;start(c,b).finish(good);check(b.files.single().exists()&&b.failures.isEmpty())}\n for(h in listOf("", "x".repeat(64), "sha256:"+hash(good)))test("malformed hash: "+h.length) {val c=context("invalid"+count);val b=Capture();Network.reset();UpdateDownloader.downloadApk(c,url,"2.0.3",b,h);check(b.failures.size==1&&Network.calls.isEmpty())}\n for(s in listOf(-1L,UpdateTransferPolicy.MAX_BYTES+1))test("invalid size: $s") {val c=context("bad-size"+count);val b=Capture();Network.reset();UpdateDownloader.downloadApk(c,url,"2.0.3",b,null,s);check(b.failures.size==1&&Network.calls.isEmpty())}\n test("chunked overrun and hard size ceiling") {val p=UpdateTransferPolicy(null,3);try{p.append(ByteArray(4),4);error("overrun admitted")}catch(_:IOException){};val q=UpdateTransferPolicy(null,0);val block=ByteArray(1024*1024);repeat(300){q.append(block,block.size)};try{q.append(byteArrayOf(0),1);error("limit admitted")}catch(_:IOException){}}\n test("older asset without digest remains supported") {check(UpdateTransferPolicy.parseAssetDigest(null)==null);check(UpdateTransferPolicy.parseAssetDigest("sha256:"+hash(good).uppercase())==hash(good))}\n test("streaming progress work bound") {val gate=UpdateProgressGate();var callbacks=0;repeat(2048){if(gate.allow(it.toLong()))callbacks++};check(callbacks==9);println("MEASURE 64MiB/32KiB, 1ms/read: 2048 old progress callbacks -> $callbacks interim + 1 completion")}\n println("COMPILE_OK: production downloader, integrity and gate. PASS $count behavioral tests; HTTP/Android/root doubles; actual filesystem/SHA-256.")\n}\n', 'Root.kt': 'package com.waenhancer.xposed.utils\nobject RootCommandRunner{fun run(c:String,t:Long):String?{throw AssertionError("Real root forbidden")}}'}

def main():
 p=argparse.ArgumentParser();p.add_argument('--root',type=Path,default=ROOT);p.add_argument('--out',type=Path);a=p.parse_args()
 with tempfile.TemporaryDirectory(prefix='waex-update-') as temp:
  out=a.out or Path(temp);out.mkdir(exist_ok=True,parents=True);src=out/'src';src.mkdir(exist_ok=True)
  files=dict(FIXTURES);files.pop('Root.kt');identities={}
  files['Context.kt']=files['Context.kt'].replace('open class Context(val cacheDir:File,val packageName:String=\"com.waenhancer\",val packageManager:PackageManager=PackageManager())', 'class AppIdentity(val uid:Int=12345)\nopen class Context(val cacheDir:File,val packageName:String=\"com.waenhancer\",val packageManager:PackageManager=PackageManager()) {val applicationInfo=AppIdentity()}')
  files['Os.kt']=files['Os.kt'].replace('object Process{fun myPid()=1;', 'object Process{fun myUid()=12345;fun myPid()=1;')
  root_source=a.root/'app/src/main/java/com/waenhancer/xposed/utils/RootCommandRunner.java'
  user_source=a.root/'app/src/main/java/com/waenhancer/utils/AndroidUserScope.java'
  root_classes=out/'root-classes';root_classes.mkdir(exist_ok=True)
  subprocess.run(['javac','--release','17','-d',str(root_classes),str(root_source),str(user_source)],check=True,timeout=30)
  identities[str(root_source.relative_to(a.root))]=hashlib.sha256(root_source.read_bytes()).hexdigest()
  identities[str(user_source.relative_to(a.root))]=hashlib.sha256(user_source.read_bytes()).hexdigest()
  for name in ['UpdateDownloader.kt','UpdateTransferPolicy.kt']:
   path=a.root/'app/src/main/java/com/waenhancer/update'/name;files[name]=path.read_text();identities[str(path.relative_to(a.root))]=hashlib.sha256(path.read_bytes()).hexdigest()
  import re
  ids=sorted(set(re.findall(r'R\.string\.([A-Za-z_][A-Za-z_0-9]*)',files['UpdateDownloader.kt'])))
  files['AppR.kt']='package com.waenhancer.app\nobject R {object string {\n'+ '\n'.join(f'const val {name} = {0x7f060100+i}' for i,name in enumerate(ids))+'\n}}'
  files['UiText.kt']='''package com.waenhancer.utils
object UiText { @JvmStatic fun get(id:Int, fallback:String, vararg args:Any?):String =
 if(args.isEmpty()) fallback else String.format(java.util.Locale.US, fallback, *args) }
'''
  for n,v in files.items():(src/n).write_text(v)
  command=['kotlinc','-classpath',str(root_classes),'-nowarn','-language-version','2.0',*map(str,src.glob('*.kt')),'-include-runtime','-d',str(out/'test.jar')]
  c=subprocess.run(command,text=True,capture_output=True,timeout=90);(out/'compile.log').write_text(c.stdout+c.stderr)
  if c.returncode:print(c.stdout+c.stderr);c.check_returncode()
  print('COMPILE_OK',flush=True)
  with tempfile.TemporaryDirectory(prefix='waex-update-files-') as fixtures:
   r=subprocess.run(['java','-cp',str(out/'test.jar')+__import__('os').pathsep+str(root_classes),'com.waenhancer.update.ChecksKt',fixtures],text=True,capture_output=True,timeout=45)
  (out/'behavior.log').write_text(r.stdout+r.stderr);print(r.stdout+r.stderr);r.check_returncode()
  (out/'source-sha256.json').write_text(json.dumps(identities,indent=2))
if __name__=='__main__':main()
